import{_ as i,o as t,c as o,a2 as a}from"./chunks/framework.CLq81i8L.js";const g=JSON.parse('{"title":"更新日志","description":"","frontmatter":{"title":"更新日志"},"headers":[],"relativePath":"editor/changelog.md","filePath":"editor/changelog.md","lastUpdated":1786325371000}'),l={name:"editor/changelog.md"};function d(r,e,n,c,u,s){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="可视化编辑器-·-更新日志" tabindex="-1">可视化编辑器 · 更新日志 <a class="header-anchor" href="#可视化编辑器-·-更新日志" aria-label="Permalink to &quot;可视化编辑器 · 更新日志&quot;">​</a></h1><blockquote><p>记录编辑器（表单 / 页面 / 大屏设计器）的主要功能迭代。 内部规划文档归档于 <code>editor/iteration-evolution.md</code>，不在此展示。</p></blockquote><h2 id="_2026-08-03-·-flex-grid-布局引擎改造" tabindex="-1">2026-08-03 · Flex -&gt; Grid 布局引擎改造 <a class="header-anchor" href="#_2026-08-03-·-flex-grid-布局引擎改造" aria-label="Permalink to &quot;2026-08-03 · Flex -&gt; Grid 布局引擎改造&quot;">​</a></h2><h3 id="布局模式改名-flex-grid" tabindex="-1">布局模式改名 flex -&gt; grid <a class="header-anchor" href="#布局模式改名-flex-grid" aria-label="Permalink to &quot;布局模式改名 flex -&gt; grid&quot;">​</a></h3><ul><li><code>BoardLayoutMode</code> 从 <code>&quot;free&quot; | &quot;flex&quot;</code> 改为 <code>&quot;free&quot; | &quot;grid&quot;</code></li><li>全量改名：类型定义、工具栏、属性面板、i18n、测试（约 30 个文件）</li><li>旧数据兼容：<code>useSchemaLoader</code> 加载时 <code>&quot;flex&quot; -&gt; &quot;grid&quot;</code> 映射</li><li>工具栏移除布局切换按钮，两种布局创建时固定不可切换</li><li>状态栏修复：根据 <code>schemaType</code> 正确显示表单/页面 + 图标</li></ul><h3 id="grid-引擎-参考-formily-grid" tabindex="-1">Grid 引擎（参考 formily Grid） <a class="header-anchor" href="#grid-引擎-参考-formily-grid" aria-label="Permalink to &quot;Grid 引擎（参考 formily Grid）&quot;">​</a></h3><ul><li>新增 <code>utils/gridEngine.ts</code>：移植 formily <code>calcSatisfyColumns</code>、<code>computeTemplateColumns</code>、<code>resolveChildSpan</code></li><li>新增 <code>composables/useGridEngine.ts</code>：Vue composable 封装，ResizeObserver + computed</li><li><code>WidgetRenderer</code> 集成：<code>flowContainerStyle</code> 用 grid engine 驱动，子节点 <code>gridColumn</code> 包裹</li><li><code>CanvasConfig.gridLayout</code>：rowGap / columnGap / minColumns / maxColumns / minWidth / maxWidth / colWrap</li><li><code>Widget.gridSpan</code>：跨列数（-1 = 撑满剩余列）</li><li>画布属性面板暴露全部 9 个 grid 参数</li><li>Widget 属性面板暴露 <code>gridSpan</code>（根级 widget）</li><li><code>boardTemplates</code> 创建时默认 gridLayout（maxColumns=3, minWidth=200）</li><li><code>widgetLayoutAdapter</code> 满宽部件默认 <code>gridSpan=-1</code></li></ul><h3 id="widget-双画布适配" tabindex="-1">Widget 双画布适配 <a class="header-anchor" href="#widget-双画布适配" aria-label="Permalink to &quot;Widget 双画布适配&quot;">​</a></h3><ul><li>移除 11 个容器 widget 的 <code>contexts: [&quot;free&quot;]</code> 限制，双模式可用</li><li>仅 <code>row-container</code> 保留 <code>contexts: [&quot;grid&quot;]</code>（24 栅格 span，grid 专属）</li></ul><h3 id="简化自-formily-编辑器不需要" tabindex="-1">简化自 formily（编辑器不需要） <a class="header-anchor" href="#简化自-formily-编辑器不需要" aria-label="Permalink to &quot;简化自 formily（编辑器不需要）&quot;">​</a></h3><ul><li>breakpoints（响应式断点）-- 编辑时固定，响应式交给运行时</li><li>strictAutoFit（严格自适应）-- span 收缩更直觉</li><li>shouldVisible（条件显示）-- 由 widget.hidden 处理</li><li>MutationObserver -- Vue 响应式替代</li><li>@formily/reactive -- 用 Vue ref/computed</li></ul><h2 id="_2026-07-20-·-e1–e3-收口" tabindex="-1">2026-07-20 · E1–E3 收口 <a class="header-anchor" href="#_2026-07-20-·-e1–e3-收口" aria-label="Permalink to &quot;2026-07-20 · E1–E3 收口&quot;">​</a></h2><h3 id="e1-大屏地基" tabindex="-1">E1 大屏地基 <a class="header-anchor" href="#e1-大屏地基" aria-label="Permalink to &quot;E1 大屏地基&quot;">​</a></h3><ul><li>文档统计对齐、视口剔除、immer 撤销、大屏 Demo</li><li>主题/动画骨架、deprecated 别名清理</li></ul><h3 id="e2-体验深化" tabindex="-1">E2 体验深化 <a class="header-anchor" href="#e2-体验深化" aria-label="Permalink to &quot;E2 体验深化&quot;">​</a></h3><ul><li>发布态模式、快捷键、埋点客户端 + dashboard</li><li>PropertyPanel 29KB -&gt; 10.1KB（拆分 6 个 composable/util）</li><li>嵌套对齐、i18n 覆盖率 ~15%</li></ul><h3 id="e3-开放生态" tabindex="-1">E3 开放生态 <a class="header-anchor" href="#e3-开放生态" aria-label="Permalink to &quot;E3 开放生态&quot;">​</a></h3><ul><li>SchemaType 注册式 + createWidgetPlugin + 第三方 Widget 指南</li><li>脚手架/市场因无外部消费者从 backlog 移除</li></ul><h2 id="度量基线" tabindex="-1">度量基线 <a class="header-anchor" href="#度量基线" aria-label="Permalink to &quot;度量基线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>数量</th></tr></thead><tbody><tr><td>Widget 目录</td><td>86</td></tr><tr><td>registerWidget</td><td>97</td></tr><tr><td>Pinia Store</td><td>12</td></tr><tr><td>Composable</td><td>46</td></tr><tr><td>Vitest 测试</td><td>~1941</td></tr></tbody></table><h2 id="更早-·-能力地基" tabindex="-1">更早 · 能力地基 <a class="header-anchor" href="#更早-·-能力地基" aria-label="Permalink to &quot;更早 · 能力地基&quot;">​</a></h2><ul><li><strong>双画布系统</strong>：Free 绝对定位 + Grid CSS Grid 布局</li><li><strong>四大配置系统</strong>：事件 / 联动 / API / 变量</li><li><strong>条件表达式</strong>：visibleOn / disabledOn / requiredOn，沙箱执行</li><li><strong>事件引擎</strong>：18 种动作类型</li><li><strong>qiankun 微前端</strong>：子应用集成</li></ul>',22)])])}const m=i(l,[["render",d]]);export{g as __pageData,m as default};
